-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.109.0',
  '2026-10-01',
  'Игры: пазл, реакция и большая правка лабиринта',
  E'Две новые игры. **Пазл** собирается из вашей картинки: выбираете размер от 3×3 до 6×6, нажимаете на два кусочка — они меняются местами. Собранные кусочки подсвечены, кнопка «Показать» даёт подсмотреть оригинал, пока держите. Картинка берётся из набора в настройках игры, а если набора нет — рисуется своя, играть можно сразу. **Реакция** — пять попыток нажать, как только поле станет зелёным; рекорд считается по лучшей попытке, а нажатие раньше времени не засчитывается.\n\nЛабиринт стал заметно удобнее.\n\nУправление переделано: вместо нажатия по всему полю — круглый джойстик в правом нижнем углу, еле заметный, чтобы не закрывать лабиринт. Куда отклонили, туда точка и едет, а изгибы коридора проходит сама. Над джойстиком крестик кнопок — шаг ровно на одну клетку (на компьютере то же делают стрелки). Старое управление иногда залипало после нескольких быстрых касаний — этого больше не будет.\n\nТупики тускнеют: если вы вернулись из ветки и смотреть там больше нечего, она становится серой — видно, куда не стоит возвращаться. В конце партии видно, сколько клеток вы прошли и сколько было в кратчайшем пути.\n\nЧасы больше не идут, пока приложение свёрнуто, а поворот телефона пересчитывает поле, не ломая партию. Стены теперь можно пополнять картинками: админ загружает бесшовную плитку в «Админке», и она встаёт в общий набор к шести нарисованным стилям.',
  E'Миграция 0159: game_textures (игра, название, файл) + раздача /uploads/textures/. Ручки: GET /games/textures?game= всем, POST|DELETE /admin/games/textures админу, экран в AdminView. Плитка размножается createPattern, бесшовность проверить нельзя — предупреждение в интерфейсе; в админке превью показано именно плиткой.\n\nmaze.go считает кратчайший путь обходом в ширину и отдаёт его в Shortest (тест: путь не короче прямого, не длиннее лабиринта, существует при любом размере). Клиент показывает его в финале и шлёт в detail рекорда.\n\nУправление: джойстик ловит жест только на себе, отпускание — pointerup/pointercancel/pointerleave (прошлая версия слушала всё поле и после пары быстрых касаний оставалась с зажатым направлением). Направление из центра клетки выбирается по порядку: отклонение джойстика → продолжение текущего коридора → вторая ось → единственный выход кроме «назад». Пункты 2 и 4 добавлены после проверки: при строго горизонтальном отклонении запасной оси нет, и точка вставала на первом же повороте. Крестик ставит цель на соседнюю клетку, движение к ней идёт тем же циклом.\n\nТупики: клиент держит стек текущего пути, шаг назад по своему следу помечает покинутую клетку тусклой, если в ней не осталось неисследованных выходов. Время партии считается суммой dt в игровом цикле, а не setInterval: requestAnimationFrame в свёрнутом приложении не вызывается, поэтому часы останавливаются сами. resize и orientationchange пересчитывают холст с задержкой 150 мс, лабиринт при этом не меняется.\n\nПазл: сетка — вариант игры (puzzle:4 и т.д.), обмен двумя нажатиями вместо перетаскивания (на телефоне внутри скроллящейся страницы оно ненадёжно), запасная картинка рисуется на canvas. Реакция: ожидание 1,5–5 с случайное, рекорд — минимум серии, средняя в detail.\n\nПроверено в браузере: серия из пяти попыток реакции с записью рекорда, сборка пазла 3×3 до победы (запись puzzle:3), в лабиринте — крестик, джойстик, подкраска тупиков, пересчёт холста при изменении ширины, загруженная текстура на стенах, прохождение подменённого лабиринта 6×6 до выхода (19 клеток при кратчайших 19, рекорд записан).'
);
-- +goose StatementEnd

